    def update_syslog_info(self, server, port=5001, protocol='UDP', msg_format='Proprietary', dscp=0, duration=10000, timeout=30):
        self.asm_licensed_v1.update_syslog_info(server=server,
                                                port=port,
                                                protocol=protocol,
                                                msg_format=msg_format,
                                                dscp=dscp,
                                                duration=duration,
                                                timeout=timeout)

