    def search_parameters_of_current_plan(self, parameter_name, raw=False, **kwargs):
        try:
            search_parameter_response = self.asm_v1.search_parameters_of_current_plan(parameter_name=parameter_name,
                                                                                      **kwargs)
            return SearchParametersASMV1.from_object_dict(search_parameter_response)

        except ApiException as e:
            if "No API found with those values API" in e.body:
                search_parameter_response = self.emservice_v1.search_parameters_of_current_plan(parameter_name=parameter_name,
                                                                                                **kwargs)
                formatted_response = SearchParametersEMSERVICE.from_object_dict(search_parameter_response)

                return self._format_parameter_to_fit_asm_response(formatted_response)
            else:
                raise e

    def _format_parameter_to_fit_asm_response(self, formatted_response):
        """
        Due to changes from CB012840 there was a need to replace removed ASM endpoints with EMSERVICE.

        Because there are differences in response structure, in order to not break backwards-compatibility
        the response goes through formating.
        """
        for item in formatted_response["items"]:
            try:
                parameter_values = json.loads(item["parameter"]["value"])
                if isinstance(parameter_values, list):
                    try:
                        item["parameter"] = self._format_simple_list_parameter(parameter_values=parameter_values)
                        item["parameter"]["simple_list_parameter"]["name"] = item["parameter_name"]

                    except TypeError:
                        item["parameter"] = self._format_complex_parameter(
                            parameter_values=parameter_values)

                    except KeyError:
                        item["parameter"] = self._format_complex_parameter_after_structure_change(
                            parameter_values=parameter_values)
                else:
                    item["parameter"] = self._format_simple_parameter(
                        parameter_values=parameter_values)

            except TypeError:
                return formatted_response

        return formatted_response

    @staticmethod
    def _format_simple_list_parameter(parameter_values):
        simple_list_parameter = {}
        value = []
        state = "unchanged"
        for parameter in parameter_values:
            value.append(parameter["currentValue"])

            if parameter["state"] != "unchanged":
                state = parameter["state"]

        simple_list_parameter["value"] = value
        simple_list_parameter["state"] = state

        return {
            "parameter_type": "simple_list",
            "simple_list_parameter": simple_list_parameter
        }

    @staticmethod
    def _format_simple_parameter(parameter_values):
        return {
            "parameter_type": "simple",
            "simple_parameter": {
                "value": parameter_values["currentValue"],
                "state": parameter_values["state"]
            }
        }

    def _format_complex_parameter(self, parameter_values):
        complex_parameter = []
        for structure in parameter_values:
            structure_parameters = []
            for parameter in structure:
                structure_parameters.append(self._get_state_and_value_for_complex_parameter(parameter))

            complex_parameter.append(structure_parameters)

        return {
            "parameter_type": "complex",
            "complex_parameter": complex_parameter
        }

    def _format_complex_parameter_after_structure_change(self, parameter_values):
        """
        After change made in https://gerrit.ext.net.nokia.com/gerrit/c/MN/MANO/OAMCU/SPEC/rest/+/8634025
        structure of complex parameter changed so that there is another level "value" in the structures
        """
        complex_parameter = []
        for structure in parameter_values:
            structure_parameters = []
            for parameter in structure["value"]:
                structure_parameters.append(self._get_state_and_value_for_complex_parameter(parameter))

            complex_parameter.append(structure_parameters)

        return {
            "parameter_type": "complex",
            "complex_parameter": complex_parameter
        }

    @staticmethod
    def _get_state_and_value_for_complex_parameter(parameter):
        return {"value": json.loads(parameter["value"])["currentValue"],
                "state": json.loads(parameter["value"])["state"],
                "name": parameter["name"]}

    def plan_validation(self, plan_id, wait_for_completion=False):
        try:
            plan_validation_info = self.asm_v1.plan_validation(plan_id=plan_id,
                                                               wait_for_completion=wait_for_completion)
            return PlanValidationASMV1.from_object_dict(plan_validation_info).to_dict()

        except ApiException as e:
            if "No API found with those values API" in e.body:
                plan_validation_info = self.emservice_v1.plan_validation(plan_id=plan_id,
                                                                         wait_for_completion=wait_for_completion)
                return PlanValidationEMSERVICEv1.from_object_dict(plan_validation_info).to_dict()
            else:
                raise e

