    @cb012840
    def get_latest_validation_result_of_delta_plan(self, plan_id, error_type, timeout=30, page_number=1,
                                                   items_per_page=20000, sort_order='desc', sorted_by=''):
        validation_results = self.asm_v1.get_latest_validation_result_of_delta_plan(plan_id=plan_id,
                                                                                    error_type=error_type,
                                                                                    timeout=timeout,
                                                                                    page_number=page_number,
                                                                                    items_per_page=items_per_page,
                                                                                    sort_order=sort_order,
                                                                                    sorted_by=sorted_by)
        return CUStagedPlanValidationResultsASMV1.from_object_dict(validation_results)

    def get_validation_result_of_staged_plan(self, plan_id, validation_id, error_type=None):
        try:
            validation_results = self.asm_v1.get_validation_result_of_staged_plan(plan_id=plan_id,
                                                                                  validation_id=validation_id,
                                                                                  error_type=error_type)
            return CUStagedPlanValidationResultsASMV1.from_object_dict(validation_results).to_dict()

        except ApiException as e:
            if "No API found with those values API" in e.body:

                if error_type and error_type not in ["definitionError", "relationError"]:
                    raise ValueError(f"Error type {error_type} is not supported for the newer SW builds,"
                                     f" please use 'definitionError' or 'relationError'")

                return self.emservice_v1.get_validation_result_of_staged_plan(plan_id=plan_id,
                                                                              validation_id=validation_id,
                                                                              error_type=error_type)
            else:
                raise e

